import { useEffect, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { TweetGroup } from '~/types/bluebird';
import { Box } from 'styled-system/jsx';
import { GroupedTweet } from '~/components/bluebird/GroupedTweet';
import { LoadingIndicator } from '~/components/bluebird/LoadingIndicator';

interface StaticReadingModeProps {
  lastReadTweetId?: string | null;
  onCurrentMonthYearChange: (monthYear: string | null) => void;
  groupedTweets: TweetGroup[];
}

export const LOCAL_STORAGE_KEY = 'bluebirdReadingModeLastReadTweetIdStatic';

export function StaticReadingMode({
  lastReadTweetId,
  onCurrentMonthYearChange,
  groupedTweets
}: StaticReadingModeProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  const [initialScrollDone, setInitialScrollDone] = useState(false);

  const virtualizer = useVirtualizer({
    count: groupedTweets.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 250, // Estimate average item size
    overscan: 5
  });

  const virtualItems = virtualizer.getVirtualItems();

  useEffect(() => {
    if (!initialScrollDone && lastReadTweetId) {
      const index = groupedTweets.findIndex((group) =>
        group.tweets.some((t) => t.id === lastReadTweetId)
      );
      if (index !== -1) {
        virtualizer.scrollToIndex(index, { align: 'start' });
      }
      setInitialScrollDone(true);
    }
  }, [lastReadTweetId, groupedTweets, virtualizer, initialScrollDone]);

  useEffect(() => {
    const scrollElement = parentRef.current;
    if (!scrollElement) return;

    const handleScroll = () => {
      const firstVisibleItemIndex = virtualizer.getVirtualItems()[0]?.index;
      if (firstVisibleItemIndex !== undefined) {
        const currentItem = groupedTweets[firstVisibleItemIndex];
        if (currentItem) {
          const idToStore = currentItem.tweets[0].id;
          localStorage.setItem(LOCAL_STORAGE_KEY, idToStore);

          const date = new Date(currentItem.group_start_time);
          const monthYear = `${date.getFullYear()}-${(date.getMonth() + 1)
            .toString()
            .padStart(2, '0')}`;
          onCurrentMonthYearChange(monthYear);
        }
      }
    };

    scrollElement.addEventListener('scroll', handleScroll);
    return () => scrollElement.removeEventListener('scroll', handleScroll);
  }, [virtualizer, groupedTweets, onCurrentMonthYearChange]);

  return (
    <Box ref={parentRef} height="calc(100vh - 64px)" overflowY="auto">
      <Box style={{ height: `${virtualizer.getTotalSize()}px`, position: 'relative' }}>
        {virtualItems.map((virtualItem) => {
          const group = groupedTweets[virtualItem.index];
          return (
            <Box
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualItem.start}px)`
              }}
            >
              {group ? (
                <GroupedTweet group={group} />
              ) : (
                <LoadingIndicator isLoading={true} hasMore={true} />
              )}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
}
